import re, subprocess, sqlite3

con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%' order by name")]

def grep_count(table, path):
    pat = rf'insert\s+(or\s+\w+\s+)?into\s+"?{re.escape(table)}"?\b'
    try:
        out = subprocess.run(['grep', '-rilE', pat, path], capture_output=True, text=True).stdout
        return [l for l in out.splitlines() if l]
    except Exception as e:
        return []

for t in tables:
    files = set()
    for path in ['scripts/migrations', 'scripts', 'tools']:
        files.update(grep_count(t, path))
    if files:
        print(t, '->', sorted(files))
PY

